    private static float[] scores(){float[] scores=new float[1000];scores[ObjectTarget.DEFAULT.index]=.92f;scores[898]=.1f;return scores;}
    private static PictureSignature signature(boolean wrong){byte[] bytes=new byte[128*128];Random random=new Random(wrong?29:7);for(int y=0;y<32;y++)for(int x=0;x<32;x++){byte value=(byte)(35+random.nextInt(190));for(int yy=0;yy<4;yy++)for(int xx=0;xx<4;xx++)bytes[(y*4+yy)*128+x*4+xx]=value;}return PictureSignature.from(bytes,128,128,0);}
